from generate_assignee_hours_report import _list_capacity_profiles
from generate_employee_performance_report import (
    _load_performance_resource_resignation_map,
    _load_support_team_members,
    _load_work_items_from_canonical_db,
    _load_worklogs_from_canonical_db,
    _list_performance_teams,
    _resolve_canonical_run_id,
)
from jira_client import BASE_URL

OUTPUT = "employee_capacity_utilization_report.html"


def _epic_for_issue(issue_key: str, items: dict[str, dict]) -> tuple[str, str]:
    current_key = str(issue_key or "").strip().upper()
    visited: set[str] = set()
    for _ in range(8):
        if not current_key or current_key in visited:
            break
        visited.add(current_key)
        item = items.get(current_key) or {}
        if "epic" in str(item.get("issue_type") or "").lower():
            return current_key, str(item.get("summary") or "")
        current_key = str(item.get("parent_issue_key") or "").strip().upper()
    return "", ""


def build_employee_capacity_utilization_payload(db: Path) -> dict:
    """Build report data from the server's authoritative canonical database."""
    run_id = _resolve_canonical_run_id(db, "")
    if not run_id:
        raise RuntimeError("Employee Capacity & Utilization requires a successful canonical refresh run.")
    items = _load_work_items_from_canonical_db(db, run_id)
    worklogs = _load_worklogs_from_canonical_db(db, run_id, items)
    for worklog in worklogs:
        epic_key, epic_summary = _epic_for_issue(str(worklog.get("issue_id") or ""), items)
        worklog["epic_key"] = epic_key
        worklog["epic_summary"] = epic_summary
    leave = list(build_rlt_leave_snapshot(db, run_id).get("daily") or [])
    names = (
        {str(row.get("assignee") or "") for row in items.values()}
        | {str(row.get("worklog_author") or row.get("issue_assignee") or "") for row in worklogs}
        | {str(row.get("assignee") or "") for row in leave}
    )
    return {
        "issues": list(items.values()),
        "worklogs": worklogs,
        "leaves": leave,
        "teams": _list_performance_teams(db),
        "profiles": _list_capacity_profiles(db),
        "support": _load_support_team_members(db),
        "resources": _load_performance_resource_resignation_map(db, sorted(name for name in names if name)),
        "canonical_run_id": run_id,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "source": "canonical_database",
        "jira_browse_base": f"{BASE_URL.rstrip('/')}/browse",
    }


